cd /exercise && node <<'NODE'
const fs = require('fs');
const assert = require('assert');

const source =
  fs.readFileSync('sum-of-multiples.js', 'utf8').replace(/export\s+const\s+sum\b/, 'const sum') +
  '\nmodule.exports = { sum };\n';
const mod = { exports: {} };
new Function('module', 'exports', source)(mod, mod.exports);
const { sum } = mod.exports;

const cases = [
  ['stated example', [3, 5], 20, 78],
  ['empty factors', [], 20, 0],
  ['duplicate factors', [3, 3, 5], 20, 78],
  ['zero factor with positive factor', [0, 3], 4, 3],
  ['only zero factor', [0], 10, 0],
  ['limit equals factor', [5], 5, 0],
  ['limit one greater than factor', [5], 6, 5],
  ['non-positive limit', [3, 5], 0, 0],
];

for (const [name, factors, limit, expected] of cases) {
  const actual = sum(factors, limit);
  assert.strictEqual(actual, expected, `${name}: expected ${expected}, got ${actual}`);
  console.log(`PASS ${name}: sum(${JSON.stringify(factors)}, ${limit}) = ${actual}`);
}

console.log('All edge-case reproducer checks passed.');
